//! Certificate inspection: `Cert` and its extensions, subject alternative
//! names and distinguished names, on certificates generated by rcgen and on
//! hand-made encodings, malformed ones included.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

mod common;

use browntls_pki::extensions::{DistributionPointName, KeyUsageBit, NameConstraints, oid};
use browntls_pki::name::attribute_type;
use browntls_pki::{
    Cert, CertificateDer, EndEntityCert, Error, GeneralName, Name, ServerName,
    anchor_from_trusted_cert,
};
use common::*;
use rcgen::{
    BasicConstraints, CidrSubnet, CrlDistributionPoint, CustomExtension, DnType, DnValue,
    ExtendedKeyUsagePurpose, GeneralSubtree, IsCa, KeyUsagePurpose, OtherNameValue, SanType,
};

const SERVER_AUTH: &[u8] = &[0x2b, 0x06, 0x01, 0x05, 0x05, 0x07, 0x03, 0x01];
const CLIENT_AUTH: &[u8] = &[0x2b, 0x06, 0x01, 0x05, 0x05, 0x07, 0x03, 0x02];
const CODE_SIGNING: &[u8] = &[0x2b, 0x06, 0x01, 0x05, 0x05, 0x07, 0x03, 0x03];
/// 1.3.6.1.4.1.55555.1, a private extension and purpose.
const PRIVATE_ARCS: &[u64] = &[1, 3, 6, 1, 4, 1, 55555, 1];
const PRIVATE_OID: &[u8] = &[0x2b, 0x06, 0x01, 0x04, 0x01, 0x83, 0xb2, 0x03, 0x01];

fn leak(der: Vec<u8>) -> &'static CertificateDer<'static> {
    Box::leak(Box::new(CertificateDer::from(der)))
}

/// A DER element (contents shorter than 64 KiB).
fn tlv(tag: u8, value: &[u8]) -> Vec<u8> {
    let mut out = vec![tag];
    match value.len() {
        n if n < 0x80 => out.push(n as u8),
        n if n < 0x100 => out.extend([0x81, n as u8]),
        n => out.extend([0x82, (n >> 8) as u8, n as u8]),
    }
    out.extend_from_slice(value);
    out
}

fn atv(oid: &[u8], tag: u8, value: &[u8]) -> Vec<u8> {
    let mut body = tlv(0x06, oid);
    body.extend(tlv(tag, value));
    tlv(0x30, &body)
}

/// An end entity signed by a fresh P-256 root, with `edit` applied to the
/// default end-entity parameters.
fn ee_with(
    edit: impl FnOnce(&mut rcgen::CertificateParams),
) -> (Chain, &'static CertificateDer<'static>) {
    let mut params = ee_params(&[]);
    edit(&mut params);
    let chain = Chain::build(
        &rcgen::PKCS_ECDSA_P256_SHA256,
        ca_params("root"),
        vec![],
        &params,
    );
    let der = leak(chain.ee_der().to_vec());
    (chain, der)
}

#[test]
fn ca_certificate_extensions() {
    let mut params = ca_params("inspected root");
    params.is_ca = IsCa::Ca(BasicConstraints::Constrained(2));
    params.key_usages = vec![
        KeyUsagePurpose::KeyCertSign,
        KeyUsagePurpose::CrlSign,
        KeyUsagePurpose::DigitalSignature,
    ];
    let mut dir = rcgen::DistinguishedName::new();
    dir.push(DnType::OrganizationName, "Permitted Org");
    params.name_constraints = Some(rcgen::NameConstraints {
        permitted_subtrees: vec![
            GeneralSubtree::DnsName("example.com".into()),
            GeneralSubtree::IpAddress(CidrSubnet::V4([10, 0, 0, 0], [255, 0, 0, 0])),
            GeneralSubtree::DirectoryName(dir),
            GeneralSubtree::Rfc822Name("example.org".into()),
        ],
        excluded_subtrees: vec![GeneralSubtree::DnsName("bad.example.com".into())],
    });
    params.crl_distribution_points = vec![CrlDistributionPoint {
        uris: vec!["http://crl.example/root.crl".into(), "ldap://x".into()],
    }];
    params.use_authority_key_identifier_extension = true;
    params.custom_extensions = vec![CustomExtension::from_oid_content(
        PRIVATE_ARCS,
        vec![0x05, 0x00],
    )];
    let key = key_for(&rcgen::PKCS_ECDSA_P256_SHA256);
    let der = leak(params.self_signed(&key).unwrap().der().to_vec());
    let cert = Cert::try_from(der).unwrap();
    assert_eq!(cert.der(), *der);

    // The generic view lists every extension once.
    let ids: Vec<&[u8]> = cert.extensions().map(|e| e.extn_id()).collect();
    for id in [
        oid::AUTHORITY_KEY_IDENTIFIER,
        oid::SUBJECT_KEY_IDENTIFIER,
        oid::BASIC_CONSTRAINTS,
        oid::KEY_USAGE,
        oid::NAME_CONSTRAINTS,
        oid::CRL_DISTRIBUTION_POINTS,
        PRIVATE_OID,
    ] {
        assert_eq!(ids.iter().filter(|i| **i == id).count(), 1, "{id:02x?}");
    }
    assert_eq!(ids.len(), 7);
    let private = cert.extension(PRIVATE_OID).unwrap();
    assert!(!private.is_critical());
    assert_eq!(private.extn_value(), [0x05, 0x00]);
    assert!(
        cert.extension(oid::BASIC_CONSTRAINTS)
            .unwrap()
            .is_critical()
    );
    assert!(cert.extension(oid::SUBJECT_ALT_NAME).is_none());
    // A decoded extension's value is the DER of its own type.
    let bc = cert.extension(oid::BASIC_CONSTRAINTS).unwrap().extn_value();
    assert_eq!(bc, [0x30, 0x06, 0x01, 0x01, 0xff, 0x02, 0x01, 0x02]);

    let bc = cert.basic_constraints().unwrap();
    assert!(bc.ca);
    assert_eq!(bc.path_len_constraint, Some(2));
    let ku = cert.key_usage().unwrap();
    for bit in KeyUsageBit::ALL {
        let expected = matches!(
            bit,
            KeyUsageBit::KeyCertSign | KeyUsageBit::CrlSign | KeyUsageBit::DigitalSignature
        );
        assert_eq!(ku.contains(bit), expected, "{bit:?}");
    }
    let ski = cert.subject_key_identifier().unwrap();
    assert_eq!(ski.len(), 20);
    let aki = cert.authority_key_identifier().unwrap();
    assert_eq!(aki.key_identifier(), Some(ski));
    assert!(aki.authority_cert_issuer().is_none());
    assert!(aki.authority_cert_serial_number().is_none());
    assert!(cert.extended_key_usage().is_none());
    assert!(cert.subject_alt_names().is_none());
    assert_eq!(cert.valid_dns_names().count(), 0);

    let mut points = cert.crl_distribution_points().unwrap();
    let point = points.next().unwrap().unwrap();
    assert!(points.next().is_none());
    assert!(point.reasons().is_none() && point.crl_issuer().is_none());
    let Some(DistributionPointName::FullName(names)) = point.distribution_point() else {
        panic!("fullName");
    };
    let uris: Vec<_> = names
        .map(|n| match n.unwrap() {
            GeneralName::UniformResourceIdentifier(u) => u,
            other => panic!("{other:?}"),
        })
        .collect();
    assert_eq!(uris, [&b"http://crl.example/root.crl"[..], b"ldap://x"]);

    let nc = cert.name_constraints().unwrap();
    let permitted: Vec<_> = nc.permitted_subtrees().unwrap().collect();
    assert_eq!(permitted.len(), 4);
    assert!(matches!(permitted[0], GeneralName::DnsName(b"example.com")));
    assert!(matches!(
        permitted[1],
        GeneralName::IpAddress(&[10, 0, 0, 0, 255, 0, 0, 0])
    ));
    let GeneralName::DirectoryName(dir) = permitted[2] else {
        panic!("directoryName");
    };
    let dir = Name::from_der(dir).unwrap();
    let attr = dir.attributes().next().unwrap();
    assert_eq!(attr.oid(), attribute_type::ORGANIZATION_NAME);
    assert_eq!(attr.as_str(), Some("Permitted Org"));
    assert!(matches!(
        permitted[3],
        GeneralName::Rfc822Name(b"example.org")
    ));
    let excluded: Vec<_> = nc.excluded_subtrees().unwrap().collect();
    assert!(matches!(
        excluded[..],
        [GeneralName::DnsName(b"bad.example.com")]
    ));

    // The trust anchor carries the same constraints.
    let anchor = anchor_from_trusted_cert(der).unwrap();
    let from_anchor =
        NameConstraints::from_contents(anchor.name_constraints.as_ref().unwrap()).unwrap();
    assert_eq!(format!("{from_anchor:?}"), format!("{nc:?}"));

    // Self-signed: issuer and subject are the same name.
    assert_eq!(cert.issuer(), cert.subject());
    let subject = Name::from_contents(cert.subject()).unwrap();
    let values: Vec<_> = subject.attributes().map(|a| a.as_str().unwrap()).collect();
    assert_eq!(values, ["inspected root", "inspected root"]);
    assert_eq!(
        Name::from_contents(&anchor.subject)
            .unwrap()
            .attributes()
            .count(),
        2
    );

    let debug = format!("{cert:?}");
    assert!(
        debug.contains("2.5.29.19") && debug.contains("inspected root"),
        "{debug}"
    );
}

#[test]
fn end_entity_extensions_through_deref() {
    let (chain, der) = ee_with(|p| {
        p.extended_key_usages = vec![
            ExtendedKeyUsagePurpose::ServerAuth,
            ExtendedKeyUsagePurpose::ClientAuth,
            ExtendedKeyUsagePurpose::CodeSigning,
            ExtendedKeyUsagePurpose::Other(PRIVATE_ARCS.to_vec()),
        ];
        p.key_usages = vec![
            KeyUsagePurpose::DigitalSignature,
            KeyUsagePurpose::ContentCommitment,
            KeyUsagePurpose::KeyEncipherment,
            KeyUsagePurpose::DataEncipherment,
            KeyUsagePurpose::KeyAgreement,
            KeyUsagePurpose::DecipherOnly,
        ];
        p.use_authority_key_identifier_extension = true;
    });
    let ee = EndEntityCert::try_from(der).unwrap();
    let cert = Cert::try_from(der).unwrap();
    // `EndEntityCert` dereferences to the same view.
    assert_eq!(format!("{:?}", *ee), format!("{cert:?}"));
    assert_eq!(ee.serial(), cert.serial());
    assert_eq!(ee.not_after(), cert.not_after());

    let purposes: Vec<_> = ee.extended_key_usage().unwrap().collect();
    assert_eq!(
        purposes,
        [SERVER_AUTH, CLIENT_AUTH, CODE_SIGNING, PRIVATE_OID]
    );
    let ku = ee.key_usage().unwrap();
    for bit in KeyUsageBit::ALL {
        let expected = !matches!(
            bit,
            KeyUsageBit::KeyCertSign | KeyUsageBit::CrlSign | KeyUsageBit::EncipherOnly
        );
        assert_eq!(ku.contains(bit), expected, "{bit:?}");
    }
    let bc = ee.basic_constraints().unwrap();
    assert!(!bc.ca && bc.path_len_constraint.is_none());

    // The authority key identifier names the root's key.
    let root_der = chain.root_der();
    let root = Cert::try_from(&root_der).unwrap();
    assert_eq!(
        ee.authority_key_identifier().unwrap().key_identifier(),
        root.subject_key_identifier()
    );
    assert_eq!(ee.issuer(), root.subject());
    assert!(ee.subject_key_identifier().is_some());
    assert!(ee.name_constraints().is_none() && ee.crl_distribution_points().is_none());
    assert_eq!(
        ee.signed_data()
            .verify_signature(ALGS, &root.subject_public_key_info()),
        Ok(())
    );
}

/// Whether `reference` matches presented identifier `presented` (a valid
/// one): equal ignoring ASCII case, or a wildcard standing for one label.
fn dns_model(presented: &str, reference: &str) -> bool {
    match presented.strip_prefix("*.") {
        Some(rest) => reference
            .split_once('.')
            .is_some_and(|(label, tail)| !label.is_empty() && tail.eq_ignore_ascii_case(rest)),
        None => presented.eq_ignore_ascii_case(reference),
    }
}

#[test]
fn subject_alt_names_of_every_kind_rcgen_emits() {
    let dns = |s: &str| SanType::DnsName(s.try_into().unwrap());
    let (_, der) = ee_with(|p| {
        p.subject_alt_names = vec![
            dns("example.com"),
            dns("*.wild.example.com"),
            dns("UPPER.Example.COM"),
            dns("bad..example"),
            dns("trailing.example."),
            dns("*.com"),
            SanType::URI("https://example.com/p".try_into().unwrap()),
            SanType::URI("spiffe://trust/x".try_into().unwrap()),
            SanType::IpAddress([192, 0, 2, 1].into()),
            SanType::IpAddress("2001:db8::1".parse().unwrap()),
            SanType::Rfc822Name("user@example.com".try_into().unwrap()),
            SanType::OtherName((
                vec![1, 3, 6, 1, 4, 1, 311, 20, 2, 3],
                OtherNameValue::Utf8String("upn@example".into()),
            )),
        ];
    });
    let ee = EndEntityCert::try_from(der).unwrap();
    let names: Vec<GeneralName<'_>> = ee
        .subject_alt_names()
        .unwrap()
        .collect::<Result<_, _>>()
        .unwrap();
    assert_eq!(names.len(), 12);
    assert!(matches!(names[3], GeneralName::DnsName(b"bad..example")));
    assert!(matches!(
        names[6],
        GeneralName::UniformResourceIdentifier(b"https://example.com/p")
    ));
    assert!(matches!(names[8], GeneralName::IpAddress(&[192, 0, 2, 1])));
    assert!(matches!(names[9], GeneralName::IpAddress(ip) if ip.len() == 16));
    assert!(matches!(
        names[10],
        GeneralName::Rfc822Name(b"user@example.com")
    ));
    let GeneralName::Other { tag: 0, value } = names[11] else {
        panic!("otherName: {:?}", names[11]);
    };
    // type-id 1.3.6.1.4.1.311.20.2.3, then [0] EXPLICIT UTF8String.
    assert!(value.starts_with(&[0x06, 0x0a, 0x2b, 0x06, 0x01, 0x04, 0x01, 0x82, 0x37]));
    assert!(value.ends_with(b"upn@example"));
    assert!(format!("{:?}", names[0]).contains("DnsName(\"example.com\")"));

    let valid: Vec<_> = ee.valid_dns_names().collect();
    assert_eq!(
        valid,
        ["example.com", "*.wild.example.com", "UPPER.Example.COM"]
    );
    let uris: Vec<_> = ee.valid_uri_names().collect();
    assert_eq!(uris, ["https://example.com/p", "spiffe://trust/x"]);

    // Name verification accepts exactly what the valid names predict.
    for reference in [
        "example.com",
        "EXAMPLE.com",
        "a.wild.example.com",
        "wild.example.com",
        "a.b.wild.example.com",
        "upper.example.com",
        "bad..example",
        "trailing.example",
        "x.com",
        "example.org",
    ] {
        let Ok(name) = ServerName::try_from(reference) else {
            continue;
        };
        let expected = valid.iter().any(|v| dns_model(v, reference));
        assert_eq!(
            ee.verify_is_valid_for_subject_name(&name).is_ok(),
            expected,
            "{reference}"
        );
    }
    for (ip, ok) in [
        ("192.0.2.1", true),
        ("2001:db8::1", true),
        ("192.0.2.2", false),
    ] {
        let name = ServerName::try_from(ip).unwrap();
        assert_eq!(ee.verify_is_valid_for_subject_name(&name).is_ok(), ok);
    }
}

#[test]
fn subject_alt_names_of_every_choice() {
    // directoryName with a multi-valued RDN (CN + C, in DER order),
    // x400Address, ediPartyName, registeredID and a dNSName, in a SAN
    // written by hand.
    let mut rdn = atv(attribute_type::COMMON_NAME, 0x0c, b"x");
    rdn.extend(atv(attribute_type::COUNTRY_NAME, 0x13, b"FI"));
    let dir_name = tlv(0x30, &tlv(0x31, &rdn));
    let mut sans = tlv(0xa4, &dir_name);
    sans.extend(tlv(0xa3, &[0x30, 0x00]));
    sans.extend(tlv(0xa5, &tlv(0xa1, &tlv(0x0c, b"party"))));
    sans.extend(tlv(0x88, &[0x2a, 0x03, 0x04]));
    sans.extend(tlv(0x82, b"example.com"));
    let san = tlv(0x30, &sans);
    let (_, der) = ee_with(|p| {
        p.custom_extensions = vec![CustomExtension::from_oid_content(&[2, 5, 29, 17], san)];
    });
    let ee = EndEntityCert::try_from(der).unwrap();
    let names: Vec<_> = ee
        .subject_alt_names()
        .unwrap()
        .map(Result::unwrap)
        .collect();
    assert_eq!(names.len(), 5);
    let GeneralName::DirectoryName(dir) = names[0] else {
        panic!("directoryName");
    };
    assert_eq!(dir, dir_name);
    let dir = Name::from_der(dir).unwrap();
    let rdns: Vec<_> = dir.iter().collect();
    assert_eq!(rdns.len(), 1);
    let values: Vec<_> = rdns[0].iter().map(|a| a.as_str().unwrap()).collect();
    assert_eq!(values, ["x", "FI"]);
    assert!(matches!(
        names[1],
        GeneralName::Other {
            tag: 3,
            value: &[0x30, 0x00]
        }
    ));
    assert!(matches!(names[2], GeneralName::Other { tag: 5, .. }));
    assert!(matches!(
        names[3],
        GeneralName::Other {
            tag: 8,
            value: &[0x2a, 0x03, 0x04]
        }
    ));
    assert_eq!(ee.valid_dns_names().collect::<Vec<_>>(), ["example.com"]);
    assert_eq!(
        format!("{:?}", names[0]),
        "DirectoryName(Name([[2.5.4.3=\"x\", 2.5.4.6=\"FI\"]]))"
    );
}

#[test]
fn distinguished_names_with_unusual_string_types() {
    use rcgen::string::{BmpString, Ia5String, PrintableString, TeletexString, UniversalString};
    let (chain, der) = ee_with(|p| {
        let dn = &mut p.distinguished_name;
        *dn = rcgen::DistinguishedName::new();
        dn.push(
            DnType::CountryName,
            DnValue::PrintableString(PrintableString::try_from("FI").unwrap()),
        );
        dn.push(DnType::StateOrProvinceName, "Uusimaa é");
        dn.push(
            DnType::LocalityName,
            DnValue::Ia5String(Ia5String::try_from("Espoo").unwrap()),
        );
        dn.push(
            DnType::OrganizationName,
            DnValue::TeletexString(TeletexString::try_from("Org").unwrap()),
        );
        dn.push(
            DnType::OrganizationalUnitName,
            DnValue::BmpString(BmpString::try_from("Un").unwrap()),
        );
        dn.push(
            DnType::CommonName,
            DnValue::UniversalString(UniversalString::try_from("Nm").unwrap()),
        );
        dn.push(
            DnType::CustomDnType(vec![0, 9, 2342, 19_200_300, 100, 1, 25]),
            DnValue::Ia5String(Ia5String::try_from("example").unwrap()),
        );
    });
    let ee = EndEntityCert::try_from(der).unwrap();
    let subject = Name::from_contents(ee.subject()).unwrap();
    let attrs: Vec<_> = subject.attributes().collect();
    let summary: Vec<_> = attrs
        .iter()
        .map(|a| (a.oid(), a.value_tag(), a.as_str(), a.value()))
        .collect();
    assert_eq!(
        summary,
        [
            (attribute_type::COUNTRY_NAME, 0x13, Some("FI"), &b"FI"[..]),
            (
                attribute_type::STATE_OR_PROVINCE_NAME,
                0x0c,
                Some("Uusimaa é"),
                "Uusimaa é".as_bytes()
            ),
            (
                attribute_type::LOCALITY_NAME,
                0x16,
                Some("Espoo"),
                &b"Espoo"[..]
            ),
            (attribute_type::ORGANIZATION_NAME, 0x14, None, &b"Org"[..]),
            (
                attribute_type::ORGANIZATIONAL_UNIT_NAME,
                0x1e,
                None,
                &b"\0U\0n"[..]
            ),
            (
                attribute_type::COMMON_NAME,
                0x1c,
                None,
                &b"\0\0\0N\0\0\0m"[..]
            ),
            (
                attribute_type::DOMAIN_COMPONENT,
                0x16,
                Some("example"),
                &b"example"[..]
            ),
        ]
    );
    // One attribute per RDN, as rcgen writes them.
    assert!(subject.iter().all(|rdn| rdn.iter().count() == 1));
    assert_eq!(
        format!("{subject:?}"),
        "Name([[2.5.4.6=\"FI\"], [2.5.4.8=\"Uusimaa é\"], [2.5.4.7=\"Espoo\"], \
         [2.5.4.10=[14]4f7267], [2.5.4.11=[1e]0055006e], [2.5.4.3=[1c]0000004e0000006d], \
         [0.9.2342.19200300.100.1.25=\"example\"]])"
    );

    // The issuer is the root's subject, also as a trust anchor.
    let root_der = chain.root_der();
    let anchor = anchor_from_trusted_cert(&root_der).unwrap();
    assert_eq!(ee.issuer(), anchor.subject.as_ref());
    let issuer = Name::from_contents(ee.issuer()).unwrap();
    let common_names: Vec<_> = issuer
        .attributes()
        .filter(|a| a.oid() == attribute_type::COMMON_NAME)
        .map(|a| a.as_str().unwrap())
        .collect();
    assert_eq!(common_names, ["root"]);
}

#[test]
fn malformed_names_are_rejected() {
    let mut rdns = tlv(0x31, &atv(attribute_type::COMMON_NAME, 0x0c, b"name"));
    rdns.extend(tlv(
        0x31,
        &atv(attribute_type::ORGANIZATION_NAME, 0x13, b"Org"),
    ));
    let der = tlv(0x30, &rdns);
    assert_eq!(Name::from_der(&der).unwrap().attributes().count(), 2);

    // Every truncation of the complete encoding.
    for len in 0..der.len() {
        assert!(Name::from_der(&der[..len]).is_err(), "{len}");
    }
    let mut trailing = der.clone();
    trailing.push(0x00);
    assert_eq!(Name::from_der(&trailing).err(), Some(Error::TrailingData));
    // Wrong outer tag, contents given as a complete name and vice versa.
    let mut set = der.clone();
    set[0] = 0x31;
    assert!(Name::from_der(&set).is_err());
    assert!(Name::from_der(&rdns).is_err());
    assert!(Name::from_contents(&der).is_err());
    // A non-minimal length.
    let mut long = vec![0x30, 0x81, rdns.len() as u8];
    long.extend(&rdns);
    assert_eq!(Name::from_der(&long).err(), Some(Error::BadDer));
    // A multi-valued RDN out of DER order (whole encodings compare, so the
    // shorter organization attribute sorts first), then in order.
    let mut unordered = atv(attribute_type::COMMON_NAME, 0x0c, b"name");
    unordered.extend(atv(attribute_type::ORGANIZATION_NAME, 0x13, b"Org"));
    let mut ordered = atv(attribute_type::ORGANIZATION_NAME, 0x13, b"Org");
    ordered.extend(atv(attribute_type::COMMON_NAME, 0x0c, b"name"));
    assert!(Name::from_contents(&tlv(0x31, &ordered)).is_ok());
    assert_eq!(
        Name::from_contents(&tlv(0x31, &unordered)).err(),
        Some(Error::BadDer)
    );
    // An empty RDN, a value with a constructed universal string tag, an
    // attribute without value.
    for bad in [
        tlv(0x31, &[]),
        tlv(0x31, &atv(attribute_type::COMMON_NAME, 0x2c, b"")),
        tlv(0x31, &tlv(0x30, &tlv(0x06, attribute_type::COMMON_NAME))),
    ] {
        assert_eq!(Name::from_contents(&bad).err(), Some(Error::BadDer));
    }
    // Oversized names are refused before parsing.
    let huge = vec![0u8; 0x10000];
    assert_eq!(Name::from_contents(&huge).err(), Some(Error::BadDer));
    // The empty name.
    assert_eq!(Name::from_der(&[0x30, 0x00]).unwrap().iter().count(), 0);
}

#[test]
fn lazily_checked_parts_report_errors() {
    // A cRLDistributionPoints extension path validation accepts (a
    // SEQUENCE OF SEQUENCE) whose only point has reasons and nothing else,
    // which RFC 5280 forbids; and an authorityKeyIdentifier whose issuer
    // names use an unknown choice.
    let dp = tlv(0x30, &tlv(0x30, &[0x81, 0x02, 0x07, 0x80]));
    let mut aki = tlv(0x80, &[1, 2, 3]);
    aki.extend(tlv(0xa1, &[0x89, 0x00]));
    aki.extend(tlv(0x82, &[0x01]));
    let (chain, der) = ee_with(|p| {
        p.custom_extensions = vec![
            CustomExtension::from_oid_content(&[2, 5, 29, 31], dp),
            CustomExtension::from_oid_content(&[2, 5, 29, 35], tlv(0x30, &aki)),
        ];
    });
    let ee = EndEntityCert::try_from(der).unwrap();
    let mut points = ee.crl_distribution_points().unwrap();
    assert_eq!(
        points.next().unwrap().err(),
        Some(Error::ExtensionValueInvalid)
    );
    assert!(points.next().is_none());
    let aki = ee.authority_key_identifier().unwrap();
    assert_eq!(aki.key_identifier(), Some(&[1, 2, 3][..]));
    assert_eq!(aki.authority_cert_serial_number(), Some(&[0x01][..]));
    let mut issuer = aki.authority_cert_issuer().unwrap();
    assert_eq!(issuer.next().unwrap().err(), Some(Error::BadDer));
    assert!(issuer.next().is_none());
    // Path validation is unaffected.
    assert_eq!(chain.verify_at(NOW), Ok(()));
}

#[test]
fn certificates_the_parser_rejects() {
    let (_, der) = ee_with(|p| {
        p.custom_extensions = vec![{
            let mut ext = CustomExtension::from_oid_content(PRIVATE_ARCS, vec![0x05, 0x00]);
            ext.set_criticality(true);
            ext
        }];
    });
    assert_eq!(
        Cert::try_from(der).err(),
        Some(Error::UnsupportedCriticalExtension)
    );
    // The same certificate is usable as a trust anchor.
    assert!(anchor_from_trusted_cert(der).is_ok());

    let (_, der) = ee_with(|_| {});
    assert!(Cert::try_from(der).is_ok());
    let mut trailing = der.to_vec();
    trailing.push(0);
    assert_eq!(
        Cert::try_from(&CertificateDer::from(trailing)).err(),
        Some(Error::TrailingData)
    );
    for len in [0, 1, 10, der.len() / 2, der.len() - 1] {
        assert!(Cert::try_from(&CertificateDer::from(&der[..len])).is_err());
    }
    // An extension value that does not match its type.
    let (_, der) = ee_with(|p| {
        p.custom_extensions = vec![CustomExtension::from_oid_content(
            &[2, 5, 29, 15],
            vec![0x05, 0x00],
        )];
    });
    assert_eq!(
        Cert::try_from(der).err(),
        Some(Error::ExtensionValueInvalid)
    );
}
